// Normalisasi + filter relevansi + dedup + batasi 5 berita/hari.
const KEYWORDS = ['harga','pangan','beras','ekonomi','anggaran','infrastruktur','banjir','subsidi','bbm','listrik','pajak','buruh','upah','petani','nelayan','kesehatan','pendidikan','digital','internet','tambang','lingkungan','inflasi','umkm'];
function hash(s){let h=2166136261;for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619);}return (h>>>0).toString(16);}
const seen = new Set();
const out = [];
for (const item of $input.all()) {
  const j = item.json;
  const headline = (j.title || '').trim();
  if (!headline) continue;
  const summary = (j.contentSnippet || j.content || j.description || '').toString().replace(/<[^>]+>/g,'').slice(0, 400);
  const lower = (headline + ' ' + summary).toLowerCase();
  if (!KEYWORDS.some(k => lower.includes(k))) continue;
  const content_hash = hash(headline.toLowerCase());
  if (seen.has(content_hash)) continue;
  seen.add(content_hash);
  out.push({ json: { headline, summary, source_url: j.link || '', source_name: (j.creator || j.author || new URL(j.link||'https://x.invalid').hostname), published_at: j.isoDate || j.pubDate || new Date().toISOString(), content_hash } });
  if (out.length >= 5) break;
}
return out;

// Parse output Claude → baris pending_events. Buang yang tidak relevan/invalid.
const resp = $json;
let text = '';
try { text = resp.content?.[0]?.text ?? ''; } catch (e) { text = ''; }
let parsed = null;
try { parsed = JSON.parse(text.replace(/^```json?\s*/i, '').replace(/```\s*$/,'').trim()); } catch (e) { parsed = null; }
if (!parsed || parsed.relevan === false) { return { json: { skip: true } }; }
const newsRow = $('Supabase: Simpan Berita').item.json;
const news = Array.isArray(newsRow) ? newsRow[0] : newsRow;
if (!news || !news.id) { return { json: { skip: true } }; }
return { json: {
  news_raw_id: news.id,
  ai_interpretation: parsed,
  draft_event: {
    title: parsed.judul_in_game || 'Kabar Arcapada',
    narasi: parsed.draft_narasi_in_game || parsed.ringkasan_netral || '',
    effects: { sektor: parsed.sektor, efek_faksi: parsed.efek_faksi || {}, efek_variabel: parsed.efek_variabel || {} },
    duration_days: parsed.duration_days || 7
  },
  skip: false
} };
